// Generated by vibelang from src/main/windows/registry.ts; the migrate flow writes it again with each batch.
// Tracks open windows and the persisted window id list used to restore
// windows (and their per-window persisted state) across app launches.
export function createWindowRegistry(persistence) {
    const windows = new Map();
    let quitting = false;
    let lastFocusedID;
    const persisted = () => {
        const value = persistence.read();
        if (!Array.isArray(value))
            return [];
        return value.filter((id) => typeof id === "string" && id.length > 0);
    };
    return {
        persisted,
        setQuitting(value = true) {
            quitting = value;
        },
        register(id, window) {
            windows.set(id, window);
            const ids = persisted();
            if (!ids.includes(id))
                persistence.write([...ids, id]);
        },
        focused(id) {
            lastFocusedID = id;
        },
        lastFocused() {
            if (!lastFocusedID)
                return;
            return windows.get(lastFocusedID);
        },
        get(id) {
            return windows.get(id);
        },
        list() {
            return [...windows.values()];
        },
        closed(id) {
            windows.delete(id);
            if (lastFocusedID === id)
                lastFocusedID = windows.keys().next().value;
            // Only a deliberate close (app keeps running with other windows open)
            // forgets a window. Closing the last window quits the app and fires
            // `closed` before `before-quit`, so treat it as a quit and keep the id
            // for restore on next launch.
            if (quitting || windows.size === 0)
                return false;
            persistence.write(persisted().filter((item) => item !== id));
            return true;
        },
    };
}
